section.codeblock:
tasks.register("buildEpub") {
    group = "publishing"
    dependsOn("installPlugin")
    doLast {
        exec {
            commandLine("dita",
                "--input=src/bookmap.ditamap",
                "--format=epub3",
                "--output=build/epub",
                "-Depub.platform=generic",
                "-Depub.theme=technical",
                "-Depub.validate=yes")
        }
    }
}

tasks.register("buildKdp") {
    group = "publishing"
    dependsOn("installPlugin")
    doLast {
        exec {
            commandLine("dita",
                "--input=src/bookmap.ditamap",
                "--format=epub3",
                "--output=build/kdp",
                "-Depub.platform=kdp",
                "-Depub.cover.image=images/cover-kdp.jpg")
        }
    }
}
